insert into public.services (id, slug, kind, image_url, gallery, price_unit, base_price, duration_options, default_duration_hours, capacity, min_units, max_units, addons, is_active, is_featured, sort_order) values (
  '557a39a3-e502-5010-af74-5cb3fb2b2a18', 'city-bike-rental', 'rental', '/images/service-rentals.jpg', '["/images/service-rentals.jpg","/images/gallery-coastal-sunset.jpg"]'::jsonb,
  'per_bike', 50, '[{"hours":1,"price":50},{"hours":2,"price":90},{"hours":4,"price":160},{"hours":8,"price":280}]'::jsonb, 4,
  12, 1, 10, '[{"id":"helmet","price":20,"name":{"en":"Extra helmet","fr":"Casque supplémentaire","ar":"خوذة إضافية"},"description":{"en":"A second helmet so you can ride with a friend.","fr":"Un second casque pour rouler à deux.","ar":"خوذة ثانية للتنقل مع صديق."}},{"id":"child-seat","price":40,"name":{"en":"Child seat","fr":"Siège enfant","ar":"مقعد أطفال"},"description":{"en":"Rear child seat fitted before you arrive, for children up to 22 kg.","fr":"Siège enfant arrière installé avant votre arrivée, jusqu’à 22 kg.","ar":"مقعد أطفال خلفي يُثبَّت قبل وصولكم، للأطفال حتى 22 كغ."}},{"id":"local-guide","price":150,"name":{"en":"Local guide","fr":"Guide local","ar":"مرشد محلي"},"description":{"en":"A licensed local guide rides with you and tells you the story of the city.","fr":"Un guide local agréé vous accompagne et raconte l’histoire de la ville.","ar":"مرشد محلي معتمد يرافقكم ويروي لكم حكاية المدينة."}},{"id":"picnic","price":60,"name":{"en":"Picnic stop","fr":"Pause pique-nique","ar":"توقف للتنزه"},"description":{"en":"Water, mint tea and Moroccan pastries delivered to a scenic stop.","fr":"Eau, thé à la menthe et pâtisseries marocaines livrés à une halte panoramique.","ar":"ماء وشاي بالنعناع وحلويات مغربية تُقدَّم في محطة بإطلالة جميلة."}}]'::jsonb,
  true, true, 1
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '557a39a3-e502-5010-af74-5cb3fb2b2a18', 'en', 'City bike rental', 'Explore Tangier at your own pace with a well-maintained city bike, helmet and lock included.',
  'Pick up a city bike near the centre of Tangier and ride wherever the day takes you — the corniche, the medina gates or a café in Malabata. Every bike is checked before it leaves, and you get a helmet, a lock and a route map. Helmets for children, child seats and extra helmets can be added when you book.', '["Helmet, lock and route map included","Bikes checked before every rental","Hourly, half-day and full-day rates"]'::jsonb, 'Bike Rental in Tangier — City Bikes from 50 MAD', 'Rent a city bike in Tangier by the hour or the day. Helmet, lock and route advice included.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '557a39a3-e502-5010-af74-5cb3fb2b2a18', 'fr', 'Location de vélo de ville', 'Découvrez Tanger à votre rythme avec un vélo de ville bien entretenu, casque et antivol inclus.',
  'Récupérez un vélo de ville près du centre de Tanger et roulez où bon vous semble : la corniche, les portes de la médina ou un café à Malabata. Chaque vélo est révisé avant chaque location, et vous recevez un casque, un antivol et une carte d’itinéraires. Casques enfants, sièges enfants et casques supplémentaires peuvent être ajoutés à la réservation.', '["Casque, antivol et carte inclus","Vélos révisés avant chaque location","Tarifs à l’heure, demi-journée et journée"]'::jsonb, 'Location de vélo à Tanger — vélos de ville dès 50 MAD', 'Louez un vélo de ville à Tanger à l’heure ou à la journée. Casque, antivol et conseils d’itinéraire inclus.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '557a39a3-e502-5010-af74-5cb3fb2b2a18', 'ar', 'تأجير دراجة المدينة', 'اكتشف طنجة على إيقاعك مع دراجة مدينة مُعتنى بها، والخوذة والقفل مشمولان.',
  'استلم دراجة مدينة قرب وسط طنجة وانطلق حيث تشاء: الكورنيش، أبواب المدينة العتيقة أو مقهى في مالاباطا. تُفحص كل دراجة قبل كل كراء، وتحصل على خوذة وقفل وخريطة للمسارات. يمكن إضافة خوذات للأطفال ومقاعد أطفال وخوذات إضافية عند الحجز.', '["الخوذة والقفل وخريطة المسارات مشمولة","فحص الدراجات قبل كل كراء","أسعار بالساعة ونصف اليوم واليوم الكامل"]'::jsonb, 'تأجير الدراجات في طنجة — دراجات المدينة من 50 درهماً', 'استأجر دراجة مدينة في طنجة بالساعة أو باليوم. الخوذة والقفل والنصائح مشمولة.'
);
insert into public.services (id, slug, kind, image_url, gallery, price_unit, base_price, duration_options, default_duration_hours, capacity, min_units, max_units, addons, is_active, is_featured, sort_order) values (
  '46cb8eca-0d71-5356-a2f3-d779c07a0a32', 'electric-bike-rental', 'rental', '/images/hero-cycling-tangier.jpg', '["/images/hero-cycling-tangier.jpg","/images/gallery-cafe-stop.jpg"]'::jsonb,
  'per_bike', 90, '[{"hours":1,"price":90},{"hours":3,"price":220},{"hours":6,"price":380},{"hours":8,"price":450}]'::jsonb, 3,
  6, 1, 6, '[{"id":"helmet","price":20,"name":{"en":"Extra helmet","fr":"Casque supplémentaire","ar":"خوذة إضافية"},"description":{"en":"A second helmet so you can ride with a friend.","fr":"Un second casque pour rouler à deux.","ar":"خوذة ثانية للتنقل مع صديق."}},{"id":"child-seat","price":40,"name":{"en":"Child seat","fr":"Siège enfant","ar":"مقعد أطفال"},"description":{"en":"Rear child seat fitted before you arrive, for children up to 22 kg.","fr":"Siège enfant arrière installé avant votre arrivée, jusqu’à 22 kg.","ar":"مقعد أطفال خلفي يُثبَّت قبل وصولكم، للأطفال حتى 22 كغ."}},{"id":"local-guide","price":150,"name":{"en":"Local guide","fr":"Guide local","ar":"مرشد محلي"},"description":{"en":"A licensed local guide rides with you and tells you the story of the city.","fr":"Un guide local agréé vous accompagne et raconte l’histoire de la ville.","ar":"مرشد محلي معتمد يرافقكم ويروي لكم حكاية المدينة."}},{"id":"picnic","price":60,"name":{"en":"Picnic stop","fr":"Pause pique-nique","ar":"توقف للتنزه"},"description":{"en":"Water, mint tea and Moroccan pastries delivered to a scenic stop.","fr":"Eau, thé à la menthe et pâtisseries marocaines livrés à une halte panoramique.","ar":"ماء وشاي بالنعناع وحلويات مغربية تُقدَّم في محطة بإطلالة جميلة."}}]'::jsonb,
  true, true, 2
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '46cb8eca-0d71-5356-a2f3-d779c07a0a32', 'en', 'Electric bike rental', 'Cover more ground with a pedal-assist e-bike — the hills between the city and Cap Spartel disappear.',
  'Our electric bikes make light work of Tangier’s hills, so you can ride out to Cap Spartel, the Caves of Hercules or the lighthouse without worrying about the climb back. You get a charged battery, a helmet and a short briefing before you leave, and we swap batteries if you plan a long day.', '["Pedal-assist e-bikes with a full battery","Helmet and briefing included","Battery swap available for long rides"]'::jsonb, 'E-Bike Rental Tangier — Electric Bikes with Helmet', 'Rent a pedal-assist electric bike in Tangier and reach Cap Spartel and the coast without the climb.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '46cb8eca-0d71-5356-a2f3-d779c07a0a32', 'fr', 'Location de vélo électrique', 'Couvrez plus de distance avec un vélo à assistance électrique : les côtes vers Cap Spartel disparaissent.',
  'Nos vélos électriques rendent les côtes de Tanger faciles : filez vers Cap Spartel, les grottes d’Hercule ou le phare sans redouter le retour. Batterie chargée, casque et briefing de prise en main compris, et nous échangeons la batterie si vous partez pour une longue journée.', '["Vélos à assistance électrique batterie pleine","Casque et briefing inclus","Échange de batterie pour les longues sorties"]'::jsonb, 'Location de vélo électrique à Tanger — casque inclus', 'Louez un vélo à assistance électrique à Tanger et rejoignez Cap Spartel sans la montée.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '46cb8eca-0d71-5356-a2f3-d779c07a0a32', 'ar', 'تأجير دراجة كهربائية', 'اقطع مسافة أطول بدراجة بمساعدة كهربائية، فتختفي المرتفعات بين المدينة ورأس سبارطيل.',
  'تجعل دراجاتنا الكهربائية مرتفعات طنجة سهلة، فتصل إلى رأس سبارطيل أو مغارة هرقل أو المنارة دون قلق من العودة صعوداً. تحصل على بطارية مشحونة وخوذة وتوجيه قصير قبل الانطلاق، ونبدّل البطارية إن خططت ليوم طويل.', '["دراجات بمساعدة كهربائية وبطارية ممتلئة","الخوذة والتوجيه مشمولان","إمكانية تبديل البطارية للرحلات الطويلة"]'::jsonb, 'تأجير الدراجات الكهربائية بطنجة — الخوذة مشمولة', 'استأجر دراجة كهربائية في طنجة وابلغ رأس سبارطيل والساحل دون عناء الصعود.'
);
insert into public.services (id, slug, kind, image_url, gallery, price_unit, base_price, duration_options, default_duration_hours, capacity, min_units, max_units, addons, is_active, is_featured, sort_order) values (
  '6eff3ec6-f558-50a1-a7d2-f11b423ad39a', 'medina-kasbah-tour', 'tour', '/images/service-tours.jpg', '["/images/service-tours.jpg","/images/gallery-group-fun.jpg"]'::jsonb,
  'per_person', 250, '[{"hours":3,"price":250}]'::jsonb, 3,
  12, 1, 12, '[{"id":"helmet","price":20,"name":{"en":"Extra helmet","fr":"Casque supplémentaire","ar":"خوذة إضافية"},"description":{"en":"A second helmet so you can ride with a friend.","fr":"Un second casque pour rouler à deux.","ar":"خوذة ثانية للتنقل مع صديق."}},{"id":"child-seat","price":40,"name":{"en":"Child seat","fr":"Siège enfant","ar":"مقعد أطفال"},"description":{"en":"Rear child seat fitted before you arrive, for children up to 22 kg.","fr":"Siège enfant arrière installé avant votre arrivée, jusqu’à 22 kg.","ar":"مقعد أطفال خلفي يُثبَّت قبل وصولكم، للأطفال حتى 22 كغ."}},{"id":"local-guide","price":150,"name":{"en":"Local guide","fr":"Guide local","ar":"مرشد محلي"},"description":{"en":"A licensed local guide rides with you and tells you the story of the city.","fr":"Un guide local agréé vous accompagne et raconte l’histoire de la ville.","ar":"مرشد محلي معتمد يرافقكم ويروي لكم حكاية المدينة."}},{"id":"picnic","price":60,"name":{"en":"Picnic stop","fr":"Pause pique-nique","ar":"توقف للتنزه"},"description":{"en":"Water, mint tea and Moroccan pastries delivered to a scenic stop.","fr":"Eau, thé à la menthe et pâtisseries marocaines livrés à une halte panoramique.","ar":"ماء وشاي بالنعناع وحلويات مغربية تُقدَّم في محطة بإطلالة جميلة."}}]'::jsonb,
  true, true, 3
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '6eff3ec6-f558-50a1-a7d2-f11b423ad39a', 'en', 'Medina & Kasbah guided ride', 'A gentle three-hour ride through the medina, the kasbah and the sea gate with a local guide.',
  'We start at the shop, roll along the bay and climb slowly into the medina, stopping at the Grand Socco, the kasbah walls and the café terraces above the strait. The pace is relaxed and made for photographs. The ride is led by a local guide who grew up in the city, and we keep groups small so there is time for questions.', '["Local guide with you for the whole ride","Small groups, relaxed pace","Photo stops above the Strait of Gibraltar"]'::jsonb, 'Guided Bike Tour of the Tangier Medina & Kasbah', 'Ride the Tangier medina and kasbah on a three-hour guided bike tour with a local guide. Small groups.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '6eff3ec6-f558-50a1-a7d2-f11b423ad39a', 'fr', 'Balade guidée médina & kasbah', 'Trois heures de balade tranquille dans la médina, la kasbah et la porte de la mer, avec un guide local.',
  'Nous partons de la boutique, longeons la baie puis montons doucement dans la médina, avec des arrêts au Grand Socco, aux remparts de la kasbah et aux terrasses de café au-dessus du détroit. Le rythme est détendu et pensé pour les photos. La balade est menée par un guide local qui a grandi dans la ville, et nous gardons des groupes réduits pour laisser place aux questions.', '["Guide local présent pendant toute la balade","Petits groupes, rythme détendu","Arrêts photo au-dessus du détroit de Gibraltar"]'::jsonb, 'Balade à vélo guidée dans la médina et la kasbah de Tanger', 'Parcourez la médina et la kasbah de Tanger lors d’une balade guidée de trois heures. Petits groupes.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '6eff3ec6-f558-50a1-a7d2-f11b423ad39a', 'ar', 'جولة مرشدة في المدينة العتيقة والقصبة', 'ثلاث ساعات من الجولة الهادئة في المدينة العتيقة والقصبة وباب البحر مع مرشد محلي.',
  'ننطلق من المتجر، ونسير بمحاذاة الخليج ثم نصعد بهدوء إلى المدينة العتيقة، مع توقفات في سوق البارود الكبير وأسوار القصبة ومقاهي التراسات المطلة على المضيق. الإيقاع هادئ ومهيأ للتصوير. يرافقكم مرشد محلي نشأ في المدينة، ونحافظ على مجموعات صغيرة لإتاحة الوقت للأسئلة.', '["مرشد محلي يرافقكم طوال الجولة","مجموعات صغيرة وإيقاع هادئ","توقفات للتصوير فوق مضيق جبل طارق"]'::jsonb, 'جولة دراجات مرشدة في مدينة طنجة العتيقة والقصبة', 'اكتشف مدينة طنجة العتيقة والقصبة في جولة دراجات مرشدة من ثلاث ساعات مع مرشد محلي.'
);
insert into public.services (id, slug, kind, image_url, gallery, price_unit, base_price, duration_options, default_duration_hours, capacity, min_units, max_units, addons, is_active, is_featured, sort_order) values (
  '3695d62f-f520-5c15-a9b6-7f3ef46260d8', 'atlantic-sunset-ride', 'tour', '/images/gallery-coastal-sunset.jpg', '["/images/gallery-coastal-sunset.jpg","/images/gallery-cafe-stop.jpg"]'::jsonb,
  'per_person', 320, '[{"hours":3.5,"price":320}]'::jsonb, 3.5,
  10, 1, 10, '[{"id":"helmet","price":20,"name":{"en":"Extra helmet","fr":"Casque supplémentaire","ar":"خوذة إضافية"},"description":{"en":"A second helmet so you can ride with a friend.","fr":"Un second casque pour rouler à deux.","ar":"خوذة ثانية للتنقل مع صديق."}},{"id":"child-seat","price":40,"name":{"en":"Child seat","fr":"Siège enfant","ar":"مقعد أطفال"},"description":{"en":"Rear child seat fitted before you arrive, for children up to 22 kg.","fr":"Siège enfant arrière installé avant votre arrivée, jusqu’à 22 kg.","ar":"مقعد أطفال خلفي يُثبَّت قبل وصولكم، للأطفال حتى 22 كغ."}},{"id":"local-guide","price":150,"name":{"en":"Local guide","fr":"Guide local","ar":"مرشد محلي"},"description":{"en":"A licensed local guide rides with you and tells you the story of the city.","fr":"Un guide local agréé vous accompagne et raconte l’histoire de la ville.","ar":"مرشد محلي معتمد يرافقكم ويروي لكم حكاية المدينة."}},{"id":"picnic","price":60,"name":{"en":"Picnic stop","fr":"Pause pique-nique","ar":"توقف للتنزه"},"description":{"en":"Water, mint tea and Moroccan pastries delivered to a scenic stop.","fr":"Eau, thé à la menthe et pâtisseries marocaines livrés à une halte panoramique.","ar":"ماء وشاي بالنعناع وحلويات مغربية تُقدَّم في محطة بإطلالة جميلة."}}]'::jsonb,
  true, true, 4
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '3695d62f-f520-5c15-a9b6-7f3ef46260d8', 'en', 'Atlantic sunset ride', 'Follow the corniche west as the light turns gold, with a mint tea stop on the cliffs.',
  'An evening ride along the Atlantic side of Tangier, timed so you are on the cliffs when the sun drops into the ocean. We ride at an easy pace, stop for mint tea and pastries, and come back through the city lights. Bring a light jacket: the wind picks up after sunset.', '["Timed for the sunset over the Atlantic","Mint tea stop included","Easy pace on quiet roads"]'::jsonb, 'Sunset Bike Ride in Tangier — Atlantic Corniche Tour', 'Join a guided sunset bike ride along the Tangier corniche, with a mint tea stop above the ocean.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '3695d62f-f520-5c15-a9b6-7f3ef46260d8', 'fr', 'Balade coucher de soleil atlantique', 'Suivez la corniche vers l’ouest quand la lumière devient dorée, avec une pause thé sur les falaises.',
  'Une balade en soirée le long de la façade atlantique de Tanger, calée pour être sur les falaises au moment où le soleil plonge dans l’océan. Nous roulons tranquillement, faisons une pause thé à la menthe et pâtisseries, puis revenons par les lumières de la ville. Prenez une veste légère : le vent se lève après le coucher du soleil.', '["Calée sur le coucher de soleil atlantique","Pause thé à la menthe incluse","Rythme facile sur des routes calmes"]'::jsonb, 'Balade à vélo au coucher du soleil à Tanger', 'Participez à une balade guidée au coucher du soleil sur la corniche de Tanger, avec pause thé.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '3695d62f-f520-5c15-a9b6-7f3ef46260d8', 'ar', 'جولة غروب الأطلسي', 'اتبع الكورنيش غرباً حين يتحول الضوء إلى ذهبي، مع توقف لشاي بالنعناع على المنحدرات.',
  'جولة مسائية على الواجهة الأطلسية لطنجة، موقوتة لتكون على المنحدرات حين تغرب الشمس في المحيط. نسير بإيقاع هادئ، ونتوقف لشاي بالنعناع والحلويات، ثم نعود عبر أضواء المدينة. خذ معك سترة خفيفة فالريح تشتد بعد الغروب.', '["موقوتة مع غروب الشمس على الأطلسي","توقف الشاي بالنعناع مشمول","إيقاع سهل على طرق هادئة"]'::jsonb, 'جولة دراجات عند الغروب في طنجة — كورنيش الأطلسي', 'شارك في جولة دراجات مرشدة عند الغروب على كورنيش طنجة مع توقف لشاي بالنعناع.'
);
insert into public.services (id, slug, kind, image_url, gallery, price_unit, base_price, duration_options, default_duration_hours, capacity, min_units, max_units, addons, is_active, is_featured, sort_order) values (
  '3c252f3a-590a-5ba1-ade4-cdda0c410284', 'cycling-lesson', 'lesson', '/images/service-lessons.jpg', '["/images/service-lessons.jpg"]'::jsonb,
  'per_person', 180, '[{"hours":1.5,"price":180}]'::jsonb, 1.5,
  4, 1, 4, '[{"id":"helmet","price":20,"name":{"en":"Extra helmet","fr":"Casque supplémentaire","ar":"خوذة إضافية"},"description":{"en":"A second helmet so you can ride with a friend.","fr":"Un second casque pour rouler à deux.","ar":"خوذة ثانية للتنقل مع صديق."}},{"id":"child-seat","price":40,"name":{"en":"Child seat","fr":"Siège enfant","ar":"مقعد أطفال"},"description":{"en":"Rear child seat fitted before you arrive, for children up to 22 kg.","fr":"Siège enfant arrière installé avant votre arrivée, jusqu’à 22 kg.","ar":"مقعد أطفال خلفي يُثبَّت قبل وصولكم، للأطفال حتى 22 كغ."}},{"id":"local-guide","price":150,"name":{"en":"Local guide","fr":"Guide local","ar":"مرشد محلي"},"description":{"en":"A licensed local guide rides with you and tells you the story of the city.","fr":"Un guide local agréé vous accompagne et raconte l’histoire de la ville.","ar":"مرشد محلي معتمد يرافقكم ويروي لكم حكاية المدينة."}},{"id":"picnic","price":60,"name":{"en":"Picnic stop","fr":"Pause pique-nique","ar":"توقف للتنزه"},"description":{"en":"Water, mint tea and Moroccan pastries delivered to a scenic stop.","fr":"Eau, thé à la menthe et pâtisseries marocaines livrés à une halte panoramique.","ar":"ماء وشاي بالنعناع وحلويات مغربية تُقدَّم في محطة بإطلالة جميلة."}}]'::jsonb,
  true, false, 5
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '3c252f3a-590a-5ba1-ade4-cdda0c410284', 'en', 'Cycling lesson', 'Learn to ride, or ride with more confidence, in a quiet spot by the sea.',
  'A one-to-one or small-group lesson for adults and children who want to learn to ride or feel safer in traffic. We start on a flat, car-free stretch near the coast, use a bike that fits you, and finish with a short ride together. Helmets are provided for everyone.', '["Private or small-group lesson","Bike and helmet provided","Flat, traffic-free practice area"]'::jsonb, 'Cycling Lessons in Tangier — Learn to Ride', 'Book a private cycling lesson in Tangier for adults or children. Bike, helmet and a calm practice area.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '3c252f3a-590a-5ba1-ade4-cdda0c410284', 'fr', 'Cours de vélo', 'Apprenez à faire du vélo, ou gagnez en confiance, dans un endroit calme au bord de la mer.',
  'Un cours individuel ou en petit groupe pour adultes et enfants qui veulent apprendre à pédaler ou se sentir plus à l’aise dans la circulation. Nous commençons sur un terrain plat et sans voitures près de la côte, avec un vélo adapté à votre taille, puis terminons par une courte sortie ensemble. Les casques sont fournis.', '["Cours individuel ou petit groupe","Vélo et casque fournis","Terrain plat et sans circulation"]'::jsonb, 'Cours de vélo à Tanger — apprendre à rouler', 'Réservez un cours de vélo privé à Tanger pour adultes ou enfants. Vélo, casque et terrain calme inclus.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '3c252f3a-590a-5ba1-ade4-cdda0c410284', 'ar', 'درس في ركوب الدراجة', 'تعلّم ركوب الدراجة أو اكتسب ثقة أكبر في مكان هادئ قرب البحر.',
  'درس فردي أو في مجموعة صغيرة للكبار والصغار الراغبين في تعلم الركوب أو الشعور بأمان أكبر في الطريق. نبدأ في مساحة مستوية خالية من السيارات قرب الساحل، بدراجة تناسب مقاسك، وننهي بجولة قصيرة معاً. الخوذات متوفرة للجميع.', '["درس فردي أو لمجموعة صغيرة","الدراجة والخوذة متوفرتان","مساحة تدريب مستوية وخالية من السيارات"]'::jsonb, 'دروس ركوب الدراجة في طنجة — تعلم الركوب', 'احجز درساً خاصاً في ركوب الدراجة بطنجة للكبار أو الصغار. الدراجة والخوذة ومكان هادئ للتدريب.'
);
insert into public.services (id, slug, kind, image_url, gallery, price_unit, base_price, duration_options, default_duration_hours, capacity, min_units, max_units, addons, is_active, is_featured, sort_order) values (
  '3de393e0-6aab-5cf0-af43-1abfeeb62d73', 'team-building-ride', 'experience', '/images/service-teambuilding.jpg', '["/images/service-teambuilding.jpg","/images/gallery-group-fun.jpg"]'::jsonb,
  'per_group', 1500, '[{"hours":3,"price":1500},{"hours":5,"price":2200}]'::jsonb, 3,
  20, 4, 20, '[{"id":"helmet","price":20,"name":{"en":"Extra helmet","fr":"Casque supplémentaire","ar":"خوذة إضافية"},"description":{"en":"A second helmet so you can ride with a friend.","fr":"Un second casque pour rouler à deux.","ar":"خوذة ثانية للتنقل مع صديق."}},{"id":"child-seat","price":40,"name":{"en":"Child seat","fr":"Siège enfant","ar":"مقعد أطفال"},"description":{"en":"Rear child seat fitted before you arrive, for children up to 22 kg.","fr":"Siège enfant arrière installé avant votre arrivée, jusqu’à 22 kg.","ar":"مقعد أطفال خلفي يُثبَّت قبل وصولكم، للأطفال حتى 22 كغ."}},{"id":"local-guide","price":150,"name":{"en":"Local guide","fr":"Guide local","ar":"مرشد محلي"},"description":{"en":"A licensed local guide rides with you and tells you the story of the city.","fr":"Un guide local agréé vous accompagne et raconte l’histoire de la ville.","ar":"مرشد محلي معتمد يرافقكم ويروي لكم حكاية المدينة."}},{"id":"picnic","price":60,"name":{"en":"Picnic stop","fr":"Pause pique-nique","ar":"توقف للتنزه"},"description":{"en":"Water, mint tea and Moroccan pastries delivered to a scenic stop.","fr":"Eau, thé à la menthe et pâtisseries marocaines livrés à une halte panoramique.","ar":"ماء وشاي بالنعناع وحلويات مغربية تُقدَّم في محطة بإطلالة جميلة."}}]'::jsonb,
  true, true, 6
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '3de393e0-6aab-5cf0-af43-1abfeeb62d73', 'en', 'Team building ride', 'A private cycling challenge for companies and groups, built around your team and your timetable.',
  'We plan a private ride for your team: a warm-up, a route with a few friendly challenges, a stop where everyone regroups, and a leader who keeps the group together whatever the fitness levels. Bikes, helmets, water and a support vehicle are included, and we can add a meal or a meeting room afterwards.', '["Private route planned around your group","Bikes, helmets and support vehicle included","Options for a meal or meeting room"]'::jsonb, 'Cycling Team Building in Tangier — Private Group Rides', 'Organise a cycling team-building experience in Tangier: private route, bikes, helmets and support vehicle.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '3de393e0-6aab-5cf0-af43-1abfeeb62d73', 'fr', 'Sortie team building', 'Un défi à vélo privé pour les entreprises et les groupes, construit autour de votre équipe et de votre emploi du temps.',
  'Nous concevons une sortie privée pour votre équipe : un échauffement, un parcours avec quelques défis amicaux, une halte pour se retrouver, et un chef de groupe qui garde tout le monde ensemble quels que soient les niveaux. Vélos, casques, eau et véhicule d’assistance inclus ; nous pouvons ajouter un repas ou une salle de réunion.', '["Parcours privé adapté à votre groupe","Vélos, casques et véhicule d’assistance","Options repas ou salle de réunion"]'::jsonb, 'Team building à vélo à Tanger — sorties privées', 'Organisez un team building à vélo à Tanger : parcours privé, vélos, casques et véhicule d’assistance.'
);
insert into public.service_translations (service_id, locale, name, short_description, description, highlights, meta_title, meta_description) values (
  '3de393e0-6aab-5cf0-af43-1abfeeb62d73', 'ar', 'جولة بناء الفريق', 'تحدٍّ خاص بالدراجات للشركات والمجموعات، مصمم حول فريقكم ووقتكم.',
  'نصمم جولة خاصة لفريقكم: تسخين، ثم مسار يتضمن تحديات ودية، وتوقف يجمع الجميع، ومشرف يحافظ على تماسك المجموعة مهما اختلفت اللياقة. الدراجات والخوذات والماء وسيارة الدعم مشمولة، ويمكن إضافة وجبة أو قاعة اجتماعات بعد الجولة.', '["مسار خاص مصمم لمجموعتكم","الدراجات والخوذات وسيارة الدعم مشمولة","خيارات وجبة أو قاعة اجتماعات"]'::jsonb, 'بناء الفريق بالدراجات في طنجة — جولات خاصة', 'نظّم تجربة بناء فريق بالدراجات في طنجة: مسار خاص ودراجات وخوذات وسيارة دعم.'
);

