  'af8face4-5d67-50b1-ae42-743b6f148121', 'sunset-ride-offer', '3695d62f-f520-5c15-a9b6-7f3ef46260d8', '/images/offer-sunset-ride.jpg',
  260, 320, 3.5, '2025-01-01', '2026-12-31',
