insert into public.offer_translations (offer_id, locale, title, short_description, description, included) values (
  'af8face4-5d67-50b1-ae42-743b6f148121', 'en', 'Sunset ride — mint tea included', 'The Atlantic sunset ride at a reduced price, with the mint tea stop on us.',
  'Book the evening ride along the Atlantic corniche at a reduced rate. The price includes the guide, the bike, the helmet and the mint tea stop on the cliffs. Available every day except during Ramadan evenings.', '["Guided 3.5-hour ride","Bike and helmet","Mint tea and pastries"]'::jsonb
);
insert into public.offer_translations (offer_id, locale, title, short_description, description, included) values (
  'af8face4-5d67-50b1-ae42-743b6f148121', 'fr', 'Balade au coucher du soleil — thé offert', 'La balade atlantique au coucher du soleil à prix réduit, pause thé à la menthe offerte.',
  'Réservez la balade du soir le long de la corniche atlantique à tarif réduit. Le prix comprend le guide, le vélo, le casque et la pause thé à la menthe sur les falaises. Disponible tous les jours sauf les soirs du Ramadan.', '["Balade guidée de 3 h 30","Vélo et casque","Thé à la menthe et pâtisseries"]'::jsonb
);
insert into public.offer_translations (offer_id, locale, title, short_description, description, included) values (
  'af8face4-5d67-50b1-ae42-743b6f148121', 'ar', 'جولة الغروب — الشاي مشمول', 'جولة غروب الأطلسي بسعر مخفض، مع توقف الشاي بالنعناع على حسابنا.',
  'احجز الجولة المسائية على كورنيش الأطلسي بسعر مخفض. يشمل السعر المرشد والدراجة والخوذة وتوقف الشاي بالنعناع على المنحدرات. متاحة كل يوم عدا أمسيات رمضان.', '["جولة مرشدة لمدة 3.5 ساعات","الدراجة والخوذة","شاي بالنعناع وحلويات"]'::jsonb
);
insert into public.offers (id, slug, service_id, image_url, price, compare_at_price, duration_hours, validity_start, validity_end, capacity, status, is_featured, sort_order) values (
  'b66814ac-6917-5aa7-a5e7-5de1d2156309', 'family-weekend-pack', '557a39a3-e502-5010-af74-5cb3fb2b2a18', '/images/gallery-group-fun.jpg',
  420, 560, 4, '2025-01-01', '2026-12-31',
  8, 'published', true, 2
);
insert into public.offer_translations (offer_id, locale, title, short_description, description, included) values (
  'b66814ac-6917-5aa7-a5e7-5de1d2156309', 'en', 'Family weekend pack', 'Four city bikes for half a day, with helmets, a child seat and a picnic stop.',
  'A half-day package for a family of four: four city bikes, four helmets, one child seat and a picnic stop with water and pastries at a viewpoint on the corniche. Available on Saturdays and Sundays, subject to availability.', '["4 city bikes for 4 hours","4 helmets and 1 child seat","Picnic stop with water and pastries"]'::jsonb
);
insert into public.offer_translations (offer_id, locale, title, short_description, description, included) values (
  'b66814ac-6917-5aa7-a5e7-5de1d2156309', 'fr', 'Pack famille du week-end', 'Quatre vélos de ville pour une demi-journée, casques, siège enfant et pause pique-nique.',
  'Un forfait demi-journée pour une famille de quatre : quatre vélos de ville, quatre casques, un siège enfant et une pause pique-nique avec eau et pâtisseries à un point de vue de la corniche. Disponible les samedis et dimanches, selon disponibilité.', '["4 vélos de ville pour 4 heures","4 casques et 1 siège enfant","Pause pique-nique eau et pâtisseries"]'::jsonb
);
insert into public.offer_translations (offer_id, locale, title, short_description, description, included) values (
  'b66814ac-6917-5aa7-a5e7-5de1d2156309', 'ar', 'عرض عطلة نهاية الأسبوع للعائلة', 'أربع دراجات مدينة لنصف يوم، مع الخوذات ومقعد أطفال وتوقف للتنزه.',
  'عرض لنصف يوم لعائلة من أربعة أفراد: أربع دراجات مدينة وأربع خوذات ومقعد أطفال وتوقف للتنزه مع الماء والحلويات في نقطة إطلالة على الكورنيش. متاح يومي السبت والأحد حسب التوفر.', '["4 دراجات مدينة لمدة 4 ساعات","4 خوذات ومقعد أطفال واحد","توقف للتنزه مع الماء والحلويات"]'::jsonb
);
insert into public.offers (id, slug, service_id, image_url, price, compare_at_price, duration_hours, validity_start, validity_end, capacity, status, is_featured, sort_order) values (
  '978e2dcf-60d7-555c-a3e7-c6dade88385f', 'ebike-day-pass', '46cb8eca-0d71-5356-a2f3-d779c07a0a32', '/images/hero-cycling-tangier.jpg',
  390, 450, 8, '2025-01-01', '2026-12-31',
  6, 'published', false, 3
);
insert into public.offer_translations (offer_id, locale, title, short_description, description, included) values (
  '978e2dcf-60d7-555c-a3e7-c6dade88385f', 'en', 'E-bike day pass', 'A full day on an electric bike, with a spare battery for the ride to Cap Spartel.',
  'Take an electric bike for the whole day and ride out to Cap Spartel, the lighthouse and the Caves of Hercules. A spare battery is included so distance is never the problem. Return before closing time (21:00).', '["E-bike for 8 hours","Spare battery","Helmet and lock"]'::jsonb
);
insert into public.offer_translations (offer_id, locale, title, short_description, description, included) values (
  '978e2dcf-60d7-555c-a3e7-c6dade88385f', 'fr', 'Forfait journée vélo électrique', 'Une journée complète en vélo électrique, avec batterie de rechange pour Cap Spartel.',
  'Prenez un vélo électrique pour la journée et roulez vers Cap Spartel, le phare et les grottes d’Hercule. Une batterie de rechange est incluse pour que la distance ne soit jamais un problème. Retour avant la fermeture (21 h).', '["Vélo électrique pendant 8 heures","Batterie de rechange","Casque et antivol"]'::jsonb
);
insert into public.offer_translations (offer_id, locale, title, short_description, description, included) values (
  '978e2dcf-60d7-555c-a3e7-c6dade88385f', 'ar', 'عرض اليوم الكامل للدراجة الكهربائية', 'يوم كامل على دراجة كهربائية، مع بطارية احتياطية لرحلة رأس سبارطيل.',
  'خذ دراجة كهربائية ليوم كامل وانطلق نحو رأس سبارطيل والمنارة ومغارة هرقل. البطارية الاحتياطية مشمولة حتى لا تكون المسافة عائقاً. الإرجاع قبل وقت الإغلاق (21:00).', '["دراجة كهربائية لمدة 8 ساعات","بطارية احتياطية","الخوذة والقفل"]'::jsonb
);

